export function compilePattern(rawInput: string, flags: string = 'g'): RegExp | null {
  try {
    const sanitized = rawInput.trim();
    return new RegExp(sanitized, flags);
  } catch (err: unknown) {
    console.error("Syntax compile error:", (err as Error).message);
    return null;
  }
}

